        def unpack(z):
            """Split a joint center/radius vector into writable arrays."""
            return z[:2 * n].reshape(n, 2), z[2 * n:]

        def smooth_positive(v):
            """Evaluate a stable softplus approximation to max(v, 0)."""
            temperature = 8.0e-4
            return temperature * np.logaddexp(0.0, v / temperature)

        def basin_penalty(z):
            """Return the squared smooth boundary and overlap violations."""
            cp, rr = unpack(z)
            edge_violation = np.column_stack(
                (rr - cp[:, 0], rr - cp[:, 1],
                 rr + cp[:, 0] - 1.0, rr + cp[:, 1] - 1.0)
            )
            edge_violation = smooth_positive(edge_violation)

            d = cp[pairs[:, 0]] - cp[pairs[:, 1]]
            dist = np.sqrt(np.sum(d * d, axis=1) + 1.0e-14)
            pair_violation = smooth_positive(
                rr[pairs[:, 0]] + rr[pairs[:, 1]] - dist
            )
            return float(
                np.sum(edge_violation * edge_violation)
                + np.sum(pair_violation * pair_violation)
            )

